{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich palm oil, a lipophilic isoprenoid with a polar chromanol head, has poor oral bioavailability in humans, supporting low absorption for the similarly lipophilic isoprenoid quinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a long-chain isoprenoid carotenoid, showed only 0.17% systemic availability from tomato paste in humans, illustrating the poor oral absorption typical of highly lipophilic isoprenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In one 13C-lycopene study, all-trans lycopene bioavailability was 23.2 ± 8%, slightly above the 20% threshold, but this contrasts with most lycopene estimates below 3%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a less-conjugated C40 isoprenoid carotenoid, showed about 58.5% absorption in humans, indicating that some long-chain isoprenoids can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a prenylated lipophilic natural product, showed high oral bioavailability from an extract, providing a limited counterexample of good absorption for a lipophilic prenylated molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is recognized as ubiquinone/CoQ10, a highly lipophilic benzoquinone with a long polyisoprenyl tail. The closest structural analogs—tocotrienols and most lycopene studies—show poor oral bioavailability, and CoQ10's known absorption behavior is low. The high values for phytoene and hyperforin are less transferable because of differences in head-group polarity, conjugation, and formulation. Overall, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (CoQ10/ubiquinone) is present in the provided records.",
    "Formulation effects are important for lipophilic isoprenoids and are not directly matched to the query.",
    "The high phytoene and hyperforin results come from different chemical classes and may not reflect CoQ10 absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

